namespace app\common\util;

/**
 * Search-table text normalizer (XVID-SCALE-BRIEF D-S2; prototype the JavCMS build tools, LAB 5.2).
 * One function for documents and queries, so the index and the query always agree. PHP 7.4+ syntax, mbstring + PCRE
 * only (no intl), byte-identical output on PHP 7.4 and 8.5.
 *
 *  - lower case, Latin diacritics folded (528-entry map, giáo viên -> giao vien, ß -> ss), HTML entities decoded twice;
 *  - ASCII words [a-z0-9]+ stay readable; codes (ACZD-094, FC2-PPV-123456) also become one joined token (aczd094);
 *  - tokens of 1-2 characters get the suffix "__" (4k -> 4k__), so no server min-token setting matters;
 *  - the 36 InnoDB default stopwords are dropped on both sides;
 *  - CJK / kana / Hangul / Thai / Lao / Khmer / Myanmar runs -> overlapping bigrams 'z' + base36(cp1) + base36(cp2)
 *    (9 characters), one character alone -> 'y' + base36(cp); other scripts -> one token 'x' + base36 per character;
 *  - field tokens tg_<tag> per tag and ac_<actor> per actor (tag / actor pages, related blocks);
 *  - every token is cut to 84 bytes (InnoDB innodb_ft_max_token_size default), in documents and in queries;
 *  - query caps: the input is cut in BYTES before normalizing; then at most 5 groups, 12 tokens in total and 8 bigrams
 *    per CJK/Thai run; the rest is dropped;
 *  - output is pure ASCII [a-z0-9_] tokens (latin1_bin column, 1 byte per character, same behaviour on every engine).
 * Numeric xvid ids are never indexed (docFromRow skips an all-digit vod_sub / vod_remarks).
 */
class FtText
{
    /** Document format version: a change means the stored documents must be rebuilt. */
    const VERSION = 1;
    const STOP = ['a'=>1,'about'=>1,'an'=>1,'are'=>1,'as'=>1,'at'=>1,'be'=>1,'by'=>1,'com'=>1,'de'=>1,'en'=>1,'for'=>1,
        'from'=>1,'how'=>1,'i'=>1,'in'=>1,'is'=>1,'it'=>1,'la'=>1,'of'=>1,'on'=>1,'or'=>1,'that'=>1,'the'=>1,'this'=>1,
        'to'=>1,'was'=>1,'what'=>1,'when'=>1,'where'=>1,'who'=>1,'will'=>1,'with'=>1,'und'=>1,'www'=>1];
    /** Query caps (D-S2, se-R8a). */
    const MAX_GROUPS = 5;
    const MAX_TOKENS = 12;
    const MAX_BIGRAMS = 8;
    /** Hard byte ceiling of a query before normalizing, whatever search_len says. */
    const QUERY_BYTES_MAX = 1024;
    /** Default byte cut when the caller passes none and no search_len is configured. */
    const QUERY_BYTES_DEFAULT = 100;
    /** Token cut in bytes (InnoDB innodb_ft_max_token_size default 84) [sc-S22]. */
    const TOKEN_MAX = 84;
    /** Bigrams kept per CJK run in a document. */
    const DOC_RUN_MAX = 120;
    /** Document size cap in bytes (cut at a token boundary). */
    const DOC_MAX = 60000;
    /** Placeholder values that are never indexed (actor, director lists). */
    const PLACEHOLDERS = ['updating'=>1,'unknown'=>1,'n/a'=>1,'-'=>1,'none'=>1];

