,'ạ'=>'a','Ả'=>'a','ả'=>'a','Ấ'=>'a','ấ'=>'a','Ầ'=>'a','ầ'=>'a','Ẩ'=>'a','ẩ'=>'a','Ẫ'=>'a','ẫ'=>'a','Ậ'=>'a','ậ'=>'a','Ắ'=>'a','ắ'=>'a','Ằ'=>'a','ằ'=>'a','Ẳ'=>'a','ẳ'=>'a','Ẵ'=>'a','ẵ'=>'a','Ặ'=>'a','ặ'=>'a','Ẹ'=>'e','ẹ'=>'e','Ẻ'=>'e','ẻ'=>'e','Ẽ'=>'e','ẽ'=>'e','Ế'=>'e','ế'=>'e','Ề'=>'e','ề'=>'e','Ể'=>'e','ể'=>'e','Ễ'=>'e','ễ'=>'e','Ệ'=>'e','ệ'=>'e','Ỉ'=>'i','ỉ'=>'i','Ị'=>'i','ị'=>'i','Ọ'=>'o','ọ'=>'o','Ỏ'=>'o','ỏ'=>'o','Ố'=>'o','ố'=>'o','Ồ'=>'o','ồ'=>'o','Ổ'=>'o','ổ'=>'o','Ỗ'=>'o','ỗ'=>'o','Ộ'=>'o','ộ'=>'o','Ớ'=>'o','ớ'=>'o','Ờ'=>'o','ờ'=>'o','Ở'=>'o','ở'=>'o','Ỡ'=>'o','ỡ'=>'o','Ợ'=>'o','ợ'=>'o','Ụ'=>'u','ụ'=>'u','Ủ'=>'u','ủ'=>'u','Ứ'=>'u','ứ'=>'u','Ừ'=>'u','ừ'=>'u','Ử'=>'u','ử'=>'u','Ữ'=>'u','ữ'=>'u','Ự'=>'u','ự'=>'u','Ỳ'=>'y','ỳ'=>'y','Ỵ'=>'y','ỵ'=>'y','Ỷ'=>'y','ỷ'=>'y','Ỹ'=>'y','ỹ'=>'y'];

    public static function b36($cp)
    {
        return str_pad(base_convert((string)$cp, 10, 36), 4, '0', STR_PAD_LEFT);
    }

    /** Cut a UTF-8 string to at most $bytes bytes without splitting a character. */
    public static function cutBytes($s, $bytes)
    {
        $s = (string)$s;
        $bytes = (int)$bytes;
        if ($bytes < 1) {
            return '';
        }
        if (strlen($s) <= $bytes) {
            return $s;
        }
        $s = substr($s, 0, $bytes);
        // drop a trailing partial multi-byte sequence
        $i = strlen($s) - 1;
        $back = 0;
        while ($i >= 0 && $back < 4 && (ord($s[$i]) & 0xC0) === 0x80) {
            $i--;
            $back++;
        }
        if ($i >= 0) {
            $lead = ord($s[$i]);
            $need = $lead >= 0xF0 ? 4 : ($lead >= 0xE0 ? 3 : ($lead >= 0xC0 ? 2 : 1));
            if ($need > 1 && $back + 1 < $need) {
                $s = substr($s, 0, $i);
            }
        }
        return $s;
    }

    private static function prep($s)
    {
        $s = (string)$s;
        if (strpos($s, '&') !== false) {
            $s = html_entity_decode(html_entity_decode($s, ENT_QUOTES | ENT_HTML5, 'UTF-8'), ENT_QUOTES | ENT_HTML5, 'UTF-8');
        }
        if (!mb_check_encoding($s, 'UTF-8')) {
            $s = mb_convert_encoding($s, 'UTF-8', 'UTF-8');
        }
        return strtr(mb_strtolower(strtr($s, self::LOWER_EXTRA), 'UTF-8'), self::$fold);
    }

    private static function cut($t)
    {
        return strlen($t) > self::TOKEN_MAX ? substr($t, 0, self::TOKEN_MAX) : $t;
    }

    /**
     * Token groups of a text: each group is a list of tokens that belong together (one word -> one token; a CJK run ->
     * its bigrams, matched as a phrase in queries). $runMax caps the bigrams per CJK run.
     */
    public static function groups($s, $runMax = self::DOC_RUN_MAX)
    {
        $s = self::prep($s);
        $groups = [];
        // codes first: ACZD-094 / fc2-ppv-123456 / 3dsvr_0001 / "aczd 094" -> joined token (pieces stay as words)
        $cands = [];
        if (preg_match_all('/(?<![a-z0-9])[a-z0-9]{1,10}(?:[-_][a-z0-9]{1,10}){1,2}(?![a-z0-9])/', $s, $cm)) { $cands = $cm[0]; }
        if (preg_match_all('/(?<![a-z0-9])[a-z]{2,6} [0-9]{2,6}(?![a-z0-9])/', $s, $cm)) { $cands = array_merge($cands, $cm[0]); }
        foreach ($cands as $c) {
            if (preg_match('/[0-9]$/', $c) && preg_match('/^[a-z0-9]*[a-z][a-z0-9]*[-_ ]/', $c)) {
                $j = preg_replace('/[-_ ]/', '', $c);
                if (strlen($j) >= 4 && strlen($j) <= 30) {
                    $groups[] = ['code' => true, 't' => [$j], 'src' => $c];
                }
            }
        }
        $run = self::SCRIPT_RUN;
        if (!preg_match_all('/[a-z0-9]+|[' . $run . ']+|[' . self::WORD_CLASS . ']+/u', $s, $m)) {
            return $groups;
        }
        foreach ($m[0] as $w) {
            if (preg_match('/^[a-z0-9]+$/', $w)) {
                if (isset(self::STOP[$w])) {
                    continue;
                }
                if (strlen($w) > 40) {
                    $w = substr($w, 0, 40);
                }
                $groups[] = ['t' => [strlen($w) < 3 ? $w . '__' : $w]];
            } elseif (preg_match('/^[' . $run . ']+$/u', $w)) {
                $cps = array_values(unpack('N*', mb_convert_encoding($w, 'UTF-32BE', 'UTF-8')));
                $n = count($cps);
                if ($n === 1) {
                    $groups[] = ['script' => true, 't' => ['y' . self::b36($cps[0])]];
                    continue;
                }
                $t = [];
                for ($i = 0; $i + 1 < $n && $i < $runMax; $i++) {
                    $t[] = 'z' . self::b36($cps[$i]) . self::b36($cps[$i + 1]);
                }
                $groups[] = ['cjk' => true, 't' => $t];
            } else {
                $cps = array_values(unpack('N*', mb_convert_encoding(mb_substr($w, 0, 20, 'UTF-8'), 'UTF-32BE', 'UTF-8')));
                $x = 'x';
                foreach ($cps as $cp) {
                    $x .= self::b36($cp);
                }
                $groups[] = ['script' => true, 't' => [self::cut($x)]];
            }
        }
        return $groups;
    }

    /** Distinct tokens of one text. */
    public static function tokens($s)
    {
        $out = [];
        foreach (self::groups($s) as $g) {
            foreach ($g['t'] as $t) {
                $out[$t] = 1;
            }
        }
        return array_keys($out);
    }

    /** Field token of a tag / actor value: tg_hd_video, ac_performer_a (one exact token per value, <= 84 bytes). */
    public static function fieldToken($prefix, $value)
    {
        $t = [];
        foreach (self::groups($value) as $g) {
            if (empty($g['code'])) {
                foreach ($g['t'] as $x) {
                    $t[] = rtrim($x, '_');
                }
            }
        }
        $tok = $prefix . '_' . implode('_', $t);
        return strlen($tok) > 3 ? rtrim(self::cut($tok), '_') : '';
    }

    /**
     * Search document of one video. $fields: title-like texts; $tags / $actors: lists; $extra: other texts (translated
     * titles). Distinct tokens, single spaces, leading + trailing space (so LIKE '% tok %' is exact).
     */
    public static function doc(array $fields, array $tags = [], array $actors = [], array $extra = [])
    {
        $set = [];
        foreach (array_merge($fields, $tags, $actors, $extra) as $text) {
            foreach (self::tokens($text) as $t) {
                $set[$t] = 1;
            }
        }
        foreach ($tags as $v) {
            if (($f = self::fieldToken('tg', $v)) !== '') { $set[$f] = 1; }
        }
        foreach ($actors as $v) {
            if (($f = self::fieldToken('ac', $v)) !== '') { $set[$f] = 1; }
        }
        if (!$set) {
            return ' ';
        }
        $s = ' ' . implode(' ', array_keys($set)) . ' ';
        return strlen($s) > self::DOC_MAX ? substr($s, 0, strrpos(substr($s, 0, self::DOC_MAX), ' ') + 1) : $s;
    }

    /** Comma lists (tags, classes, actors): trimmed values without placeholders, distinct, in order. */
    public static function splitList($value)
    {
        $out = [];
        foreach (preg_split('/[,\x{FF0C}\x{3001}]/u', (string)$value) ?: [] as $v) {
            $v = trim($v);
            if ($v === '' || isset(self::PLACEHOLDERS[mb_strtolower($v, 'UTF-8')])) {
                continue;
            }
            $out[$v] = 1;
        }
        return array_keys($out);
    }

    /**
     * Document of a javcms_vod row (D-S2): title, English title, code (vod_sub / vod_remarks unless all digits: numeric
     * xvid ids are never indexed), real director, tags (vod_tag + vod_class), actors, plus $titles (translated titles of
     * the languages chosen in search.ft_langs).
     */
    public static function docFromRow(array $row, array $titles = [])
    {
        $name = (string)($row['vod_name'] ?? '');
        $fields = [$name];
        $en = (string)($row['vod_en'] ?? '');
        if ($en !== '' && $en !== $name) {
            $fields[] = $en;
        }
        $codes = [];
        foreach (['vod_sub', 'vod_remarks'] as $k) {
            $c = trim((string)($row[$k] ?? ''));
            if ($c !== '' && !ctype_digit($c) && !isset($codes[strtolower($c)]) && strlen($c) <= 64) {
                $codes[strtolower($c)] = 1;
                $fields[] = $c;
            }
        }
        foreach (self::splitList($row['vod_director'] ?? '') as $d) {
            $fields[] = $d;
        }
        $tags = array_values(array_unique(array_merge(self::splitList($row['vod_tag'] ?? ''), self::splitList($row['vod_class'] ?? ''))));
        $actors = self::splitList($row['vod_actor'] ?? '');
        $extra = [];
        foreach ($titles as $t) {
            $t = (string)$t;
            if ($t !== '' && $t !== $name && $t !== $en) {
                $extra[] = $t;
            }
        }
        return self::doc($fields, $tags, $actors, $extra);
    }

    /** Byte limit for a visitor query: search_len (bytes) when configured, never above QUERY_BYTES_MAX. */
    public static function queryBytes($maxBytes = 0)
    {
        $maxBytes = (int)$maxBytes;
        if ($maxBytes < 1 && isset($GLOBALS['config']['app']['search_len'])) {
            $maxBytes = (int)$GLOBALS['config']['app']['search_len'];
        }
        if ($maxBytes < 1) {
            $maxBytes = self::QUERY_BYTES_DEFAULT;
        }
        return min($maxBytes, self::QUERY_BYTES_MAX);
    }

    /**
     * Query plan of a visitor word: ['groups' => token groups, 'boolean' => InnoDB boolean string, 'tokens' => flat
     * distinct tokens, 'prefix' => true when the last group may be matched as a prefix on the walk path (D2, se-R8b)].
     * The input is cut to queryBytes($maxBytes) BYTES before normalizing (search_len, GET and POST alike). Every token is
     * [a-z0-9_]: no boolean operator, quote or wildcard of the visitor reaches the server.
     */
    public static function query($wd, $maxBytes = 0)
    {
        $wd = trim(self::cutBytes(is_scalar($wd) ? (string)$wd : '', self::queryBytes($maxBytes)));
        $groups = self::groups($wd, self::MAX_BIGRAMS);
        $codes = array_values(array_filter($groups, function ($g) { return !empty($g['code']); }));
        if ($codes) {
            // a code query: the joined token is the precise term; drop the pieces it was made of
            $pieces = [];
            foreach ($codes as $c) {
                preg_match_all('/[a-z0-9]+/', $c['src'], $pm);
                foreach ($pm[0] as $p) { $pieces[] = strlen($p) < 3 ? $p . '__' : $p; }
            }
            $groups = array_values(array_filter($groups, function ($g) use ($pieces) {
                return !empty($g['code']) || count($g['t']) !== 1 || !in_array($g['t'][0], $pieces, true);
            }));
        }
        $seen = [];
        $out = [];
        $budget = self::MAX_TOKENS;
        foreach ($groups as $g) {
            if (count($out) >= self::MAX_GROUPS || $budget < 1) {
                break;
            }
            $t = [];
            foreach ($g['t'] as $x) {
                $x = self::cut($x);
                if (preg_match('/^[a-z0-9_]{1,84}$/D', $x)) {
                    $t[] = $x;
                }
            }
            if (!$t) {
                continue;
            }
            if (count($t) > $budget) {
                $t = array_slice($t, 0, $budget);
            }
            $k = implode(' ', $t);
            if (isset($seen[$k])) {
                continue;
            }
            $seen[$k] = 1;
            $g['t'] = $t;
            $budget -= count($t);
            $out[] = $g;
        }
        $tokens = [];
        foreach ($out as $g) {
            foreach ($g['t'] as $x) {
                $tokens[$x] = 1;
            }
        }
        $last = $out ? $out[count($out) - 1] : null;
        $prefix = $last !== null && empty($last['code']) && empty($last['cjk']) && empty($last['script']) && count($last['t']) === 1 && preg_match('/^[a-z0-9]{3,84}$/D', $last['t'][0]) === 1;
        return ['groups' => $out, 'boolean' => self::booleanOf($out), 'tokens' => array_keys($tokens), 'prefix' => $prefix];
    }

    /** Query plan of a field token (tag / actor pages): one exact token, or no group when it is not a valid token. */
    public static function tokenQuery($token)
    {
        $token = is_string($token) ? $token : '';
        if (!preg_match('/^(tg|ac)_[a-z0-9_]{1,81}$/D', $token)) {
            return ['groups' => [], 'boolean' => '', 'tokens' => [], 'prefix' => false];
        }
        $g = [['t' => [$token]]];
        return ['groups' => $g, 'boolean' => self::booleanOf($g), 'tokens' => [$token], 'prefix' => false];
    }

    public static function booleanOf(array $groups)
    {
        $b = [];
        foreach ($groups as $g) {
            $b[] = count($g['t']) > 1 ? '+"' . implode(' ', $g['t']) . '"' : '+' . $g['t'][0];
        }
        return implode(' ', $b);
    }
}
